            readback_data_var[0] = field_storage.cpu_fifo.tx.trigger.tready.value;
        end
        if(rd_mux_addr == 14'h34) begin
            readback_data_var[0] = hwif_in.cpu_fifo.tx.status.tvalid.next;
        end
        if(rd_mux_addr == 14'h38) begin
            readback_data_var[7:0] = hwif_in.uart.rx.data.next;
            readback_data_var[30] = hwif_in.uart.rx.oflow.next;
            readback_data_var[31] = hwif_in.uart.rx.valid.next;
        end
        if(rd_mux_addr == 14'h3c) begin
            readback_data_var[0] = field_storage.uart.rx_trigger.read.value;
        end
        if(rd_mux_addr == 14'h40) begin
            readback_data_var[7:0] = field_storage.uart.tx.data.value;
            readback_data_var[31] = hwif_in.uart.tx.busy.next;
        end
        if(rd_mux_addr == 14'h44) begin
            readback_data_var[0] = field_storage.uart.tx_trigger.write.value;
        end
        if(rd_mux_addr == 14'h48) begin
            readback_data_var[0] = hwif_in.gpio.key1.next;
            readback_data_var[1] = hwif_in.gpio.key2.next;
            readback_data_var[8] = field_storage.gpio.led1.value;
            readback_data_var[9] = field_storage.gpio.led2.value;
        end
        for(int i0=0; i0<4; i0++) begin
            if(rd_mux_addr == 14'h4c + (14)'(i0) * 14'hc) begin
                readback_data_var[1:0] = hwif_in.ethernet[i0].status.speed.next;
            end
            if(rd_mux_addr == 14'h50 + (14)'(i0) * 14'hc) begin
                readback_data_var[15:0] = field_storage.ethernet[i0].mac_47_32.mac.value;
            end
            if(rd_mux_addr == 14'h54 + (14)'(i0) * 14'hc) begin
                readback_data_var[31:0] = field_storage.ethernet[i0].mac_31_0.mac.value;
            end
        end
        if(rd_mux_addr == 14'h7c) begin
            readback_data_var[15:0] = 16'hcaca;
            readback_data_var[31:16] = 16'hccba;
        end
        if(rd_mux_addr == 14'h80) begin
            readback_data_var[15:0] = 16'h0;
            readback_data_var[23:16] = 8'h0;
            readback_data_var[31:24] = 8'h1;
        end
        if(rd_mux_addr == 14'h84) begin
            readback_data_var[0] = hwif_in.dpe.fcr.idle.next;
            readback_data_var[1] = field_storage.dpe.fcr.pause.value;
        end
        if(rd_mux_addr == 14'h88) begin
            readback_data_var[31:0] = field_storage.cycle.count.value;
        end
        if((rd_mux_addr >= 14'h400) && (rd_mux_addr <= 14'h400 + 14'h3ff)) begin
            readback_data_var = hwif_in.routing_table.rd_data;
        end
        if((rd_mux_addr >= 14'h2000) && (rd_mux_addr <= 14'h2000 + 14'h1dff)) begin
            readback_data_var = hwif_in.cryptokey_table.rd_data;
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr & ~decoded_req_is_external;
        readback_err = '0;
    end

    assign external_rd_ack = readback_external_rd_ack;
    assign cpuif_rd_ack = readback_done | readback_external_rd_ack;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
